# Correct tidyverse code with the patterns most likely to trip a column checker.
# r-colcheck must report nothing here.
library(tidyverse)
sales <- read_csv("data/sales.csv")
cols <- c("region", "year")
f <- function(df, col) df %>% filter({{ col }} > 0) %>% mutate(v = .data[[col]])
g <- function(by) sales %>% group_by(across(all_of(by))) %>% summarise(t = sum(amount))
h <- sales %>% mutate(label = glue::glue("{region}-{year}"), region2 = str_to_upper(region))
i <- sales %>% select(all_of(cols), amount) %>% filter(if_any(everything(), is.na))
j <- sales %>% filter(.data$amount > 0, !is.na(customer)) %>% mutate(idx = row_number(), grp = cur_group_id())
k <- sales %>% summarise(across(c(amount, year), mean), .by = region) %>% mutate(zz = amount)
l <- sales %>% mutate(year = as.integer(year), bucket = case_when(amount > 5 ~ "hi", TRUE ~ "lo"), ratio = amount / threshold2)
threshold2 <- 3
m <- sales %>% janitor::clean_names() %>% select(region)
n2 <- sales %>% rename_with(toupper) %>% select(REGION)
o <- sales %>% left_join(tibble(region = "North", pop = 5), by = "region") %>% mutate(pc = amount / pop)
p <- sales %>% pivot_longer(c(amount, year), names_to = "key", values_to = "val") %>% filter(key == "amount", val > 1)
q <- sales |> distinct(region, .keep_all = TRUE) |> arrange(desc(amount))
r <- sales %>% nest(data = -region) %>% mutate(n = map_int(data, nrow))
s2 <- sales %>% transmute(region, amt2 = amount * 2) %>% filter(amt2 > 1)
t2 <- ggplot(sales, aes(year, amount)) + geom_point(aes(colour = region)) + facet_wrap(~ customer) + labs(x = NULL)
u <- sales %>% mutate(name = paste(region, year)) %>% separate(name, c("a", "b")) %>% select(a)
v <- with(sales, mean(amount))
w <- sales$amount * 2
x <- sales[sales$year > 2019, c("region", "amount")]
y <- sales %>% filter(amount > quantile(amount, 0.9)) %>% slice_max(amount, n = 3)
z <- sales %>% group_by(region) %>% mutate(rank = min_rank(desc(amount))) %>% ungroup() %>% filter(rank == 1)
k2 <- sales %>% mutate(m = mean(amount), .by = c(region, year)) %>% select(region, m)
keys <- c("region")
k3 <- sales %>% summarise(m = mean(amount), .by = dplyr::all_of(keys)) %>% mutate(z = m)
k4 <- sales %>% slice_max(amount, n = 1, by = region)
k5 <- sales %>% summarise(m = mean(amount), .by = all_of(c("region", "year"))) %>% select(region, year, m)
k6 <- sales %>% select(dplyr::all_of("region")) %>% mutate(r2 = region)
k7 <- sales %>% summarise(m = mean(amount), .by = dplyr::any_of("regoin"))
level <- "year"
k8 <- sales %>% group_by(across(c(region, year))) %>% summarise(m = mean(amount)) %>% mutate(z = region + year + m)
k9 <- sales %>% group_by(across(all_of(c("region", level)))) %>% summarise(m = mean(amount)) %>% mutate(z = region)
k10 <- sales %>% mutate(across(where(is.numeric), mean))
k11 <- sales %>% mutate(across(all_of(keys), sum))
k12 <- sales %>% mutate(across(c(amount, year), ~ .x / amount))
k13 <- sales %>% mutate(across(amount, scale_amount_defined_elsewhere))
k14 <- sales %>% mutate(across(c(amount, starts_with("y")), mean))
k15 <- sales %>% group_by(pick(everything())) %>% summarise(n = n()) %>% mutate(z = region)
k16 <- sales %>% rowwise() %>% mutate(s = sum(c_across(amount:year)))
k17 <- sales %>% group_by(yr = year * 2) %>% summarise(m = mean(amount)) %>% mutate(z = yr + m)
k18 <- sales %>% group_by(across(starts_with("re"))) %>% mutate(z = amount) %>% filter(z > 1)
k19 <- sales %>% select(all_of("region"), starts_with("am"))
v1 <- sales %>% pull(amount) %>% unique()
v2 <- sales %>% pull(-1)
v3 <- pull(sales, region)
n1 <- sales %>% filter(amount > 0) %>% nrow()
nm1 <- sales %>% names()
v1 %>% sort()
u1 <- tibble(id = 1, data = list(tibble(d = 1, r = 2))) %>% unnest(data) %>% filter(d == 1, r == 2, id == 1)
u2 <- tibble(id = 1, data = list(tibble(d = 1, r = 2))) %>% unnest_longer(data) %>% select(id, data)
u3 <- tibble(id = 1, data = list(tibble(d = 1, r = 2))) %>% hoist(data, first = "d", second = list("r", 1)) %>% select(id, first, second, data)
k20 <- sales %>% mutate(across(c(amount, year), as.character, .names = "{.col}_chr")) %>% select(amount, amount_chr, year_chr)
k21 <- sales %>% mutate(across(c(amount), list(m = mean, s = sd))) %>% select(amount, amount_m, amount_s)
k22 <- sales %>% mutate(across(c(amount), list(mean, sd))) %>% select(amount_1, amount_2)
k23 <- sales %>% transmute(across(c(region, amount), identity), r2 = region) %>% select(region, amount, r2)
k24 <- sales %>% summarise(across(where(is.numeric), mean), .by = region) %>% mutate(z = zz)
k25 <- sales %>% group_by(region) %>% summarise(across(c(amount), mean)) %>% mutate(z = region + amount)
k26 <- sales %>% mutate(across(c(amount), mean, .names = "mean_{.col}_{.fn}")) %>% select(mean_amount_1)
k27 <- sales %>% mutate(across(c(amount, year), ~ .x * 2, .names = "{col}2")) %>% select(amount2, year2, region)
scores <- readRDS("data/scores.rds")
b1 <- bind_rows(sales, scores) %>% select(region, score, id)
b2 <- bind_rows(sales, scores, .id = "src") %>% select(src, region)
b3 <- sales %>% group_by(region) %>% bind_rows(scores) %>% summarise(n = n()) %>% mutate(z = region + n)
b4 <- bind_rows(sales, unknown_frame) %>% select(zz)
b5 <- bind_cols(sales, scores) %>% select(zz)
b6 <- purrr::list_rbind(list(sales, scores), names_to = "which") %>% select(which, region, score)
b7 <- sales |> bind_rows(scores) |> select(id, year)
b8 <- bind_rows(sales |> mutate(.src = "a"), scores |> mutate(.src = "s")) |> arrange(desc(.src)) |> select(.src, id, region)
u4 <- tibble(id = 1, data = list(tibble(d = 1, r = 2))) %>% hoist(.col = data, first = "d") %>% select(id, first, data)
s1 <- sales %>% split(.$region) %>% purrr::map(~ .x %>% filter(amount > 1)) %>% bind_rows() %>% select(region, amount)
s2 <- sales %>% group_by(region) %>% group_split() %>% purrr::imap(~ .x %>% mutate(grp = .y)) %>% bind_rows() %>% select(grp, region)
s3 <- lapply(split(sales, sales$region), function(d) d %>% select(region, amount)) %>% bind_rows() %>% select(region)
s4 <- sales %>% split(.$region) %>% purrr::map_dfr(~ .x %>% summarise(total = sum(amount))) %>% select(total)
s5 <- sales %>% split(.$region) %>% purrr::map(~ .x %>% select(all_of(unknown_cols))) %>% bind_rows() %>% select(zz)
keep_two <- function(d) d %>% select(region, amount)
s6 <- sales %>% split(.$region) %>% purrr::map(keep_two) %>% bind_rows() %>% select(region, amount)
s7 <- purrr::map(sales, ~ .x)
s8 <- sales %>% group_by(region) %>% group_split(.keep = FALSE) %>% purrr::map(~ .x %>% select(amount, year)) %>% bind_rows()
req <- c("region", "amount")
s9 <- sales %>% select(all_of(req)) %>% mutate(z = region + amount)
s10 <- sales %>% summarise(m = mean(amount), .by = all_of(req)) %>% select(region, amount, m)
